flow.chain:
THEN(
    startPrepareRequest,
    IF(
        startExists,
        startResume,
        THEN(
            startPrepareInstance,
            startExecute
        )
    )
);

THEN(
    completePrepare,
    completeExecute,
    IF(
        completeNeedAutoPass,
        completeAutoPass,
        noop
    )
);

THEN(
    taskOpPrepare,
    taskOpLoad,
    taskOpExecute,
    IF(
        taskOpNeedNotify,
        taskOpNotify,
        noop
    )
);
